                ", nombre=" + nombre + ", descripcion=" + descripcion + ", sitioWeb=" + sitioWeb +
                ", nuevaPassword=" + (nuevaPassword != null ? "[PROVIDED]" : "null") +
                ", imagenUrl=" + (imagenUrl != null ? "[data-or-url]" : "null"));

