            }
            if (costoTurista < 0 || costoEjecutivo < 0 || costoEquipajeExtra < 0) {
                response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
                out.print("{\"success\": false, \"error\": \"Los costos no pueden ser negativos\"}");
