            }

            // Comprobar duplicado por nombre en esta aerolínea
            List<DtRutaVuelo> rutasExistentes = sistema.listarRutasPorAerolinea(nombreAerolinea);
            if (rutasExistentes != null) {
                for (DtRutaVuelo r : rutasExistentes) {
