            // Procesar imagen (parte 'imagenRuta' o dataURL) si viene
            String imagenUrl = "";
            Part imagePart = null;
            try {
                imagePart = request.getPart("imagenRuta");
            } catch (IllegalStateException | ServletException | IOException ignored) {
